public sealed class RecordingTemplateStore : ITemplateStore
{
    private readonly string? _value;

    public RecordingTemplateStore(string? value)
    {
        _value = value;
    }

    public List<string> Calls { get; } = new List<string>();

    public string? Get(string key)
    {
        Calls.Add(key);
        return _value;
    }
}

